import threading

def reproduce(connect, service) -> str | None:
    # read initial balance
    try:
        with connect() as conn:
            row = conn.execute("SELECT balance FROM accounts WHERE id = %s", (1,)).fetchone()
            if row is None:
                return None
            init_bal = row[0]
    except Exception:
        return None

    N = 24
    AMOUNT = 100
    barrier = threading.Barrier(N)
    results = [None] * N

    def worker(idx):
        try:
            with connect() as conn:
                try:
                    barrier.wait(timeout=15)
                except Exception as e:
                    results[idx] = e
                    return
                try:
                    service.deposit(conn, 1, AMOUNT)
                    results[idx] = True
                except Exception as e:
                    results[idx] = e
        except Exception as e:
            results[idx] = e

    threads = [threading.Thread(target=worker, args=(i,)) for i in range(N)]
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=30)

    # count successes: deposit should succeed; any True counts
    success = sum(1 for r in results if r is True)
    # if threads failed to run, don't report
    if success == 0:
        return None
    # expected balance: init + success*AMOUNT (failed ones didn't change balance)
    # Note: if some raised unexpected error, we only count True; to be safe
    # if there were errors that shouldn't happen on correct code, ignore them
    # unless they indicate lost update anyway - just check balance vs successes
    try:
        with connect() as conn:
            row = conn.execute("SELECT balance FROM accounts WHERE id = %s", (1,)).fetchone()
            final_bal = row[0]
    except Exception:
        return None

    expected = init_bal + success * AMOUNT
    if final_bal != expected:
        return f"lost update: account 1 balance is {final_bal} but {success} successful deposits of {AMOUNT} on top of {init_bal} should give {expected} (missing {expected - final_bal})"
    return None

